from typing import List
from concurrent.futures import ThreadPoolExecutor

# Mock interface for clarity
class HtmlParser:
    def getUrls(self, url: str) -> List[str]:
        ...

def get_hostname(url: str) -> str:
    # Extracts host from URL, assumes http:// is always present and no port/query
    return url.split('/')[2]

def crawl(startUrl: str, htmlParser: 'HtmlParser') -> List[str]:
    hostname = get_hostname(startUrl)
    visited = {startUrl}
    frontier = [startUrl]

    with ThreadPoolExecutor(max_workers=8) as executor:
        while frontier:
            next_frontier = []
            # Fetch all pages of the current level concurrently
            for links in executor.map(htmlParser.getUrls, frontier):
                for link in links:
                    if link not in visited and get_hostname(link) == hostname:
                        visited.add(link)
                        next_frontier.append(link)
            frontier = next_frontier
    return list(visited)
```
*Notes:*
- The above is a level-by-level BFS: the (slow) `getUrls` calls of each level run concurrently in the thread pool.
- Thread safety comes from only the main thread touching `visited` and the frontier; worker threads only call `getUrls`, so no lock is needed.
- ThreadPoolExecutor is used for multi-threading.
